return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'mn','project-id-version'=>'babilim-0.1.0-mn-babilim-0.1.0-mn-20261030T030647','pot-creation-date'=>'2026-10-30T06:25:34+00:00','po-revision-date'=>'2026-10-30T06:25:34+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Таны сайтад суулгасан плагин болон загваруудын дутуу орчуулгыг нөхнө.','Translations'=>'Орчуулгууд','Babilim Settings'=>'Babilim-ийн тохиргоо','Settings'=>'Тохиргоо','You are not allowed to do this.'=>'Танд энэ үйлдлийг хийх эрх байхгүй.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Цөөн бүрэлдэхүүн хэсэг сонгоно уу: нэг удаад дээд тал нь %1$d үйлдэл хийнэ (та %2$d сонгосон байна).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Энэ бүрэлдэхүүн хэсэг уг сайтад суулгаагүй тул түүнд орчуулга хүсэх боломжгүй.','Already installed.'=>'Аль хэдийн суулгасан.','Downloaded and installed.'=>'Татаж аваад суулгасан.','Babilim has not been enabled for this site yet.'=>'Babilim энэ сайтад хараахан идэвхжээгүй байна.','No build is available to download for this locale.'=>'Энэ хэлний татаж авах боломжтой хувилбар байхгүй байна.','Rolled back to the previous build.'=>'Өмнөх хувилбар руу буцаалаа.','Rolled back and reported.'=>'Буцаагаад мэдэгдлээ.','Rolled back, but the report could not be sent: %s'=>'Буцаасан боловч тайланг илгээж чадсангүй: %s','Removed.'=>'Устгасан.','Translation requested.'=>'Орчуулга хүссэн.','This component was already uploaded. Babilim is checking it now.'=>'Энэ бүрэлдэхүүн хэсгийг аль хэдийн байршуулсан. Babilim одоо шалгаж байна.','Upload cancelled.'=>'Байршуулалтыг цуцалсан.','Upload complete — translation requested.'=>'Байршуулалт дууслаа — орчуулга хүссэн.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Энэ бүрэлдэхүүн хэсэг хувилбарын дугаараа зарлаагүй тул түүнд орчуулга хүсэх боломжгүй.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Энэ бүрэлдэхүүн хэсгийн хувилбарын дугаар %d тэмдэгтээс урт бөгөөд Babilim үүнийг боловсруулж чадахгүй тул орчуулга хүсэх боломжгүй.','A translation cannot be requested for that locale on this site right now.'=>'Одоогоор энэ сайтад тухайн хэлний орчуулга хүсэх боломжгүй.','Thank you. Your report was sent.'=>'Баярлалаа. Таны тайланг илгээлээ.','This report does not name a valid plugin or theme and locale.'=>'Энэ тайлан хүчинтэй плагин эсвэл загвар болон хэлийг заагаагүй байна.','Please choose a category for this report.'=>'Энэ тайланд зориулж ангилал сонгоно уу.','This report is missing a valid build to report against.'=>'Энэ тайланд холбогдох хүчинтэй хувилбар алга байна.','This build is not one this site currently knows about for this component/locale.'=>'Энэ хувилбар нь уг бүрэлдэхүүн хэсэг/хэлний хувьд сайтад одоогоор мэдэгдэж буй хувилбар биш байна.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" талбар хэт урт байна: %2$d тэмдэгттэй бөгөөд дээд хязгаар нь %3$d. Юу ч илгээгээгүй; богиносгоод дахин оролдоно уу.','Original string'=>'Жинхэнэ мөр','String context'=>'Мөрийн контекст','Current translation'=>'Одоогийн орчуулга','Suggested translation'=>'Санал болгосон орчуулга','Note (optional)'=>'Тайлбар (заавал биш)','Where you saw this (optional)'=>'Үүнийг хаанаас харсан бэ (заавал биш)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim-ийн синхрончлолыг үйлчилгээ түр хойшлуулсан (хүсэлтийн хязгаар); %s дараа дахин оролдоно.','The locale you added is not valid: use a WordPress locale code such as ll_CC (letters, digits, underscore, hyphen or @, at most %d characters). Nothing was saved.'=>'Таны нэмсэн хэл буруу байна: ll_CC гэх мэт WordPress-ийн хэлний кодыг ашиглана уу (үсэг, тоо, доогуур зураас, зураас эсвэл @, дээд тал нь %d тэмдэгт). Юу ч хадгалагдсангүй.','Settings saved.'=>'Тохиргоог хадгаллаа.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Хэрэв үүнийг идэвхжүүлбэл устгах үед энэ сайтын таниулбар мөн устана. Дараа нь энэ сайтад холбосон төлбөртэй лицензийг автоматаар сэргээх боломжгүй; үүнийг сэргээхийн тулд та Babilim-ийн дэмжлэгтэй %s хаягаар холбогдох шаардлагатай.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim нь плагиныг устгах үед энэ сайтын таниулбарыг устгахаар тохируулагдсан байна. Тэгвэл энэ сайтад холбосон төлбөртэй лицензийг автоматаар сэргээх боломжгүй; та Babilim-ийн дэмжлэгтэй %s хаягаар холбогдох хэрэгтэй. Таниулбарыг хадгалахын тулд Cancel дарж, Babilim-ийн тохиргооноос "Устгах үед Babilim-ийн бүх өгөгдлийг устгах" сонголтыг болиулаад дахин идэвхгүй болгоно уу. Ямар ч байсан идэвхгүй болгох уу?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Энэ сүлжээний %1$d сайт плагиныг устгах үед Babilim-ийн таниулбараа устгахаар тохируулагдсан байна. Тэгвэл тэр сайтад холбосон төлбөртэй лицензийг автоматаар сэргээх боломжгүй; та Babilim-ийн дэмжлэгтэй %2$s хаягаар холбогдох хэрэгтэй. Таниулбарыг хадгалахын тулд Cancel дарж, тухайн сайтын Babilim-ийн тохиргооноос "Устгах үед Babilim-ийн бүх өгөгдлийг устгах" сонголтыг болиулаад дахин идэвхгүй болгоно уу. Ямар ч байсан идэвхгүй болгох уу?' . "\0" . 'Энэ сүлжээний %1$d сайт плагиныг устгах үед Babilim-ийн таниулбараа устгахаар тохируулагдсан байна. Тэгвэл тэдгээр сайтад холбосон төлбөртэй лицензийг автоматаар сэргээх боломжгүй; та Babilim-ийн дэмжлэгтэй %2$s хаягаар холбогдох хэрэгтэй. Таниулбаруудыг хадгалахын тулд Cancel дарж, сайт бүрийн Babilim-ийн тохиргооноос "Устгах үед Babilim-ийн бүх өгөгдлийг устгах" сонголтыг болиулаад дахин идэвхгүй болгоно уу. Ямар ч байсан идэвхгүй болгох уу?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Энэ сүлжээнд сайтууд хэт олон тул тэдгээрийг нэг нэгээр нь шалгах боломжгүй бөгөөд зарим сайт нь плагиныг устгах үед Babilim-ийн таниулбараа устгахаар тохируулагдсан байж магадгүй. Ийм сайтад холбогдсон төлбөртэй лицензийг автоматаар сэргээх боломжгүй болно; та Babilim-ийн дэмжлэгтэй %s хаягаар холбогдох шаардлагатай болно. Таниулбаруудыг хадгалахын тулд Cancel дарж, сайт бүрийн Babilim тохиргооноос "Устгах үед Babilim-ийн бүх өгөгдлийг устгах" сонголтын тэмдгийг арилгаад, дахин идэвхгүй болгоно уу. Ямар ч байсан идэвхгүй болгох уу?','Open Babilim settings'=>'Babilim-ийн тохиргоог нээх','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim энэ сайтыг баталгаажуулж чадаагүй тул юу ч татаж аваагүй, суулгаагүй.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Үйлчилгээ таны сайтад хүрч чадсангүй. Галт хана, аюулгүй байдлын плагин эсвэл хостын дүрэм хүсэлтийг хаасан байж магадгүй; /wp-json/babilim/v1/challenge руу хандах хүсэлтийг зөвшөөрнө үү.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Таны сайт хэт удаан хариу өглөө. Дараа дахин оролдож, хост тань хэт удаан эсвэл ачаалал ихтэй биш эсэхийг шалгана уу.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Таны сайт хариу өгсөн боловч хүлээгдэж байсан хариу биш байлаа. REST API-г өөр плагин өөрчилсөн эсвэл тэр төгсгөлийн цэг кэшлэгдсэн байж магадгүй; /wp-json/babilim/v1/challenge-г кэшлэх болон дахин бичихээс чөлөөлнө үү.','Please check that your site can be reached from the internet, then try again.'=>'Таны сайтад интернетээс хандах боломжтой эсэхийг шалгаад дахин оролдоно уу.','Re-verify'=>'Дахин баталгаажуулах','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Энэ сайт нэг удаагийн синхрончлолд үйлчилгээний хүлээн авах хэмжээнээс хэтэрсэн тул зарим зүйл орхигдсон: %1$d бүрэлдэхүүн хэсэг ба %2$d хэл.','This site is verified.'=>'Энэ сайт баталгаажсан.','Registration restarted.'=>'Бүртгэлийг дахин эхлүүллээ.','Sync complete.'=>'Синхрончлол дууслаа.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim энэ сайтыг идэвхжүүлж, шалгаж байна… Энэ хуудсыг дахин ачаалах эсвэл хуваарьт шалгалт дуустал хүлээнэ үү.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim идэвхжүүлэлтийг дуусгаж чадсангүй (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Нэг удаад зөвхөн нэг PHP хүсэлт боловсруулдаг хост энэ алхмыг дуусгаж чадахгүй.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim идэвхжлээ: энэ сайт баталгаажсан бөгөөд %d бүрэлдэхүүн хэсэг олдлоо.' . "\0" . 'Babilim идэвхжлээ: энэ сайт баталгаажсан бөгөөд %d бүрэлдэхүүн хэсэг олдлоо.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim идэвхгүй боллоо. Цаашид юу ч илгээгдэхгүй; суулгасан орчуулгууд үргэлжлүүлэн ажиллана.','Supplementary translation index rebuilt.'=>'Нэмэлт орчуулгын индексийг дахин үүсгэлээ.','Sweep complete: %d file deleted.'=>'Цэвэрлэгээ дууслаа: %d файл устгагдлаа.' . "\0" . 'Цэвэрлэгээ дууслаа: %d файл устгагдлаа.','Removed %d installed component.'=>'Суулгасан %d бүрэлдэхүүн хэсгийг хаслаа.' . "\0" . 'Суулгасан %d бүрэлдэхүүн хэсгийг хаслаа.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Автомат суулгалт одоо унтраалттай байна; хэрэв хүсвэл тохиргооноос дахин асаана уу.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim энэ сайт дээрх таны хэлний орчуулгагүй плагин, сэдвүүдийг олж, тус бүрт нь орчуулга суулгана.','Languages found on this site: %s.'=>'Энэ сайтаас олдсон хэлүүд: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Боломжтой орчуулгуудыг нэг товшилтоор суулгаж, байхгүйг нь хүсэж болно. Үүний дараа шинэ орчуулга болон шинэчлэлтүүд автоматаар суулгагдана (үнэгүй багцад зөвхөн үнэгүй байрыг аль хэдийн ашиглаж буй плагин, сэдвүүдэд).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Үнэгүй багц хязгаарлагдмал тооны плагин, сэдвийг хамарна; Babilim-г идэвхжүүлсний дараа таны яг квот Тохиргоо хэсэгт харагдана.','What is sent when you enable Babilim'=>'Babilim-г идэвхжүүлэхэд юу илгээгдэх вэ','Enabling…'=>'Идэвхжүүлж байна…','Enable Babilim'=>'Babilim-г идэвхжүүлэх','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Идэвхжүүлэх дээр дарснаар та дээр жагсаасан мэдээллийг Babilim руу илгээхийг зөвшөөрч байна.','Check again now'=>'Одоо дахин шалгах','Babilim installed %d translation automatically since your last visit.'=>'Babilim таны сүүлд зочилсноос хойш %d орчуулгыг автоматаар суулгалаа.' . "\0" . 'Babilim таны сүүлд зочилсноос хойш %d орчуулгыг автоматаар суулгалаа.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim энэ сайтыг идэвхжүүлж, шалгаж байна… (сүүлийн оролдлого: %s)','Check again'=>'Дахин шалгах','No components synced yet.'=>'Бүрэлдэхүүн хэсэг хараахан синхрончлогдоогүй байна.','%d succeeded'=>'%d амжилттай' . "\0" . '%d амжилттай','%d skipped'=>'%d алгассан' . "\0" . '%d алгассан','%d failed'=>'%d амжилтгүй' . "\0" . '%d амжилтгүй','%d not yet tried'=>'%d хараахан оролдоогүй' . "\0" . '%d хараахан оролдоогүй','Bulk %s:'=>'Бөөнөөр %s:','%1$s nothing to do.'=>'%1$s хийх зүйл алга.','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Үргэлжлүүлж байна…','Continue next batch (%d left)'=>'Дараагийн багцыг үргэлжлүүлэх (%d үлдсэн)','Search components'=>'Бүрэлдэхүүн хэсгүүдийг хайх','These are the languages this site uses. You can change them in %s.'=>'Эдгээр нь энэ сайтын ашигладаг хэлүүд юм. Та тэдгээрийг %s хэсгээс өөрчлөх боломжтой.','Upload this component?'=>'Энэ бүрэлдэхүүн хэсгийг байршуулах уу?','There is no upload waiting for confirmation.'=>'Баталгаажуулалт хүлээж буй байршуулалт алга.','Back'=>'Буцах','To translate this component, Babilim needs its source.'=>'Энэ бүрэлдэхүүн хэсгийг орчуулахын тулд Babilim-д түүний эх код хэрэгтэй.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'%1$s (хувилбар %2$s)-ийн плагин эсвэл сэдвийн бүх лавлахыг Babilim руу байршуулна.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Хэрэв тэр лавлахад түлхүүр, лог эсвэл үйлчлүүлэгчийн өгөгдөл байвал тэдгээр мөн байршуулагдана. Үйлчилгээ нь түгээмэл эмзэг файлуудыг (тохиргоо, орчин, өгөгдлийн сангийн дамп, лог, түлхүүр) устгадаг ч бүгдийг нь олно гэдгийг баталгаажуулж чадахгүй.','The upload is kept until you ask Babilim to delete it.'=>'Та Babilim-ээс устгахыг хүсэх хүртэл байршуулсан өгөгдөл хадгалагдана.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Үүнийг үйлчилгээний хостинг үзүүлэгч хадгалж, орчуулга гаргахын тулд хиймэл оюун ухааны загварууд боловсруулна.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Эх текст болон түүнээс гарсан орчуулгуудыг ижил хувилбарыг суулгасан бусад сайтуудад өгөх болно.','By continuing you confirm that you have the right to upload this component.'=>'Үргэлжлүүлснээр та энэ бүрэлдэхүүн хэсгийг байршуулах эрхтэй гэдгээ баталгаажуулж байна.','Upload and request'=>'Байршуулж, хүсэлт илгээх','Uploading…'=>'Байршуулж байна…','Cancel'=>'Цуцлах','Uploading'=>'Байршуулж байна','There is no upload in progress.'=>'Явагдаж буй байршуулалт алга.','Uploading part %1$d of %2$d…'=>'%2$d-аас %1$d-р хэсгийг байршуулж байна…','Continue'=>'Үргэлжлүүлэх','Confirm'=>'Баталгаажуулах','Remove'=>'Устгах','Roll back'=>'Буцаах','Nothing to confirm.'=>'Баталгаажуулах зүйл алга.','Choose a language'=>'Хэл сонгох','Roll back and report'=>'Буцааж, мэдэгдэх','Report a problem'=>'Асуудлыг мэдэгдэх','Nothing to choose.'=>'Сонгох зүйл алга.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Хэлийг сонгоно уу.','Supplementary translations'=>'Нэмэлт орчуулгууд','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Бүрэлдэхүүн хэсэг тус бүрийн хэл тус бүрийн хуваалцсан үндсэн домэйны нэмэлтэд оруулсан хувь нэмэр.','Component'=>'Бүрэлдэхүүн хэсэг','Language'=>'Хэл','Included in index'=>'Индексэд орсон','Entries'=>'Бичлэгүүд','Conflicting keys'=>'Зөрчилтэй түлхүүрүүд','Yes'=>'Тийм','No — component inactive'=>'Үгүй — бүрэлдэхүүн хэсэг идэвхгүй','No — installed version differs from the active one'=>'Үгүй — суулгасан хувилбар идэвхтэй хувилбараас өөр байна','No — component removed'=>'Үгүй — бүрэлдэхүүн хэсэг устгагдсан','No'=>'Үгүй','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Үүнийг зөвхөн сүлжээний администратор хийж чадна, учир нь энэ нь энэ сүлжээний бүх сайтад хуваалцдаг орчуулгын файлуудыг өөрчилдөг.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim энэ сайтыг баталгаажуулж дуусгаж чадсангүй (үйлчилгээ сайтад буцаж холбогдож чадсангүй). Бүртгэл түр зогссон.','This site already has an active registration that can no longer be recovered automatically.'=>'Энэ сайт идэвхтэй бүртгэлтэй боловч түүнийг автоматаар сэргээх боломжгүй болсон.','Restart registration'=>'Бүртгэлийг дахин эхлүүлэх','Babilim settings'=>'Babilim-ийн тохиргоо','General'=>'Ерөнхий','Advanced'=>'Нарийвчилсан','Languages'=>'Хэлүүд','Automatic installs'=>'Автомат суулгалт','Install available translations automatically'=>'Боломжтой орчуулгуудыг автоматаар суулгах','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'Үнэгүй багц дээр зөвхөн таны үнэгүй слотуудын аль нэгийг аль хэдийн ашиглаж байгаа бүрэлдэхүүн хэсгүүдийг автоматаар суулгана, тиймээс шинэ слот эзлэхгүй.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Энэ сайт олон сайтын сүлжээний нэг хэсэг бөгөөд шинэ орчуулгыг автоматаар суулгадаггүй. Аль хэдийн суулгасан орчуулгууд хэвээр шинэчлэгдэнэ.','Custom overrides'=>'Өөрийн тохируулсан орчуулгууд','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Бүгдийг цэвэрлэх эсвэл энэ плагиныг устгахдаа миний өөрийн орчуулгын тохируулгуудыг хадгалах.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Таны %s дотор байрлуулсан орчуулгын файлууд Babilim-ийнхээс үргэлж давуу эрхтэй. Та үүнийг сонгохоо болихгүй л бол тэдгээр хадгалагдана.','Uninstall'=>'Устгах','Delete all Babilim data on uninstall'=>'Устгах үед Babilim-ийн бүх өгөгдлийг устгах','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Анхдагчаар унтраалттай: плагиныг устгахад энэ сайтын таниулбар хадгалагддаг тул дахин суулгахад ашиглах боломжтой.','Account'=>'Бүртгэл','Save changes'=>'Өөрчлөлтийг хадгалах','Disable Babilim'=>'Babilim-г идэвхгүй болгох','Installed translations are kept, but no further checks or downloads will run.'=>'Суулгасан орчуулгууд хадгалагдах боловч цаашид шалгалт, татаж авалт хийгдэхгүй.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim-г идэвхгүй болгох уу? Суулгасан орчуулгууд хадгалагдах боловч цаашид шалгалт, татаж авалт хийгдэхгүй.','This site is not registered with Babilim yet.'=>'Энэ сайт Babilim-д хараахан бүртгэгдээгүй байна.','This site is already licensed. Reload the page.'=>'Энэ сайт аль хэдийн лицензтэй байна. Хуудсыг дахин ачаална уу.','Checkout is not available for this site right now.'=>'Тооцоо одоогоор энэ сайтад боломжгүй байна.','Could not start checkout: %s'=>'Тооцоог эхлүүлж чадсангүй: %s','Babilim is not enabled.'=>'Babilim идэвхжээгүй байна.','Not registered yet'=>'Одоогоор бүртгээгүй','Not verified'=>'Баталгаажаагүй','Verified'=>'Баталгаажсан','Status'=>'Төлөв','Licensed'=>'Лицензтэй','Partner'=>'Түнш','Free'=>'Үнэгүй','License'=>'Лиценз','Upgrade this site'=>'Энэ сайтыг сайжруулах','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Энэ сайтад зориулсан нэг удаагийн худалдан авалт: %1$s %2$s. Ирээдүйн бүх орчуулгын шинэчлэлтийг агуулна. Төлбөрийг Paddle шинэ табд боловсруулна.','This issues a new restore code and the previous one stops working. Continue?'=>'Энэ нь шинэ сэргээх код олгох бөгөөд өмнөх код ажиллахаа болино. Үргэлжлүүлэх үү?','Show a new restore code'=>'Шинэ сэргээх код харуулах','rc_…'=>'rc_…','Restore code'=>'Сэргээх код','Restore purchase'=>'Худалдан авалтыг сэргээх','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Өмнө нь энэ домайнд зориулсан лиценз худалдан авч байсан уу? Тооцоо хийх үедээ авсан сэргээх кодоо оруулна уу.','That does not look like a restore code.'=>'Энэ нь сэргээх код шиг харагдахгүй байна.','This restore code was not recognised for this site.'=>'Энэ сэргээх кодыг энэ сайтад танихгүй байна.','Too many attempts. Try again tomorrow.'=>'Хэт олон оролдлого хийлээ. Маргааш дахин оролдоно уу.','This site must be verified first.'=>'Эхлээд энэ сайтыг баталгаажуулах шаардлагатай.','Could not restore the purchase: %s'=>'Худалдан авалтыг сэргээж чадсангүй: %s','Purchase restored. This site is now licensed.'=>'Худалдан авалт сэргэлээ. Энэ сайт одоо лицензтэй боллоо.','This site has no purchase to show a code for.'=>'Энэ сайтад код харуулах худалдан авалт алга.','Could not show a new restore code: %s'=>'Шинэ сэргээх код харуулж чадсангүй: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Таны шинэ сэргээх код: %s. Аюулгүй газар хадгална уу — өмнөх код ажиллахаа больсон.','What is sent when Babilim checks this site'=>'Babilim энэ сайтыг шалгахад юу илгээгддэг вэ','(detected)'=>'(илрүүлсэн)','No language is managed yet.'=>'Одоогоор удирдаж буй хэл алга.','Babilim adds translations for every language checked here.'=>'Babilim энд сонгосон бүх хэлний орчуулгыг нэмдэг.','Add another language'=>'Өөр хэл нэмэх','Choose a language…'=>'Хэл сонгох…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Үйлчилгээнээс WordPress.org-ийн бүх хэлний жагсаалтыг ачаалж чадсангүй тул одоогоор өөр хэл нэмэх боломжгүй.','Theme'=>'Сэдэв','Plugin'=>'Плагин','Free quota'=>'Үнэгүй квот','Downloads: %1$d/%2$d (%3$s)'=>'Татаж авалт: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Нэмэлт орчуулгын индекс','Built'=>'Бүтээгдсэн','Included'=>'Орсон','Excluded'=>'Хасагдсан','Already in WordPress core'=>'WordPress-ийн цөмд аль хэдийн байгаа','Supplementary translation maintenance'=>'Нэмэлт орчуулгын засвар үйлчилгээ','Maintenance status is not available right now.'=>'Засвар үйлчилгээний төлөвийг одоогоор харах боломжгүй байна.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Цэвэрлэгээг %1$s үед түр зогсоосон: %2$s. Юу ч устгагдаагүй.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Сүүлийн цэвэрлэгээ %1$s: %2$d шинээр тэмдэглэгдсэн, %3$d файл устгагдсан, %4$d бичлэг хасагдсан.','No cleanup has run yet.'=>'Цэвэрлэгээ хараахан ажиллаагүй байна.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Орчуулгын индексийн бичилт %1$s үед өөр хүсэлттэй зөрчилдсөн (%2$s) тул хэрэгжээгүй; хамгийн сүүлийн хувилбарыг хадгалсан.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Орчуулгын индексийн %1$s үеийн бичилт (%2$s) дуусгах боломжгүй байсан тул хэрэгжээгүй (%3$s).','Maintenance'=>'Засвар үйлчилгээ','Rebuild index now'=>'Индексийг одоо дахин үүсгэх','Sweep now'=>'Одоо цэвэрлэх','Danger zone'=>'Аюултай бүс','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Babilim-ийн энэ сайтын бүх плагин болон загварт суулгасан бүх хэлний файлыг устгана.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim-ийн суулгасан бүхнийг устгах уу? Энэ нь Babilim-ийн энэ сайтын бүх плагин болон загварт суулгасан бүх хэлний файлыг устгана.','Remove everything Babilim installed'=>'Babilim-ийн суулгасан бүгдийг устгах','This string is too long to be sent as a report, so no report form is offered for it.'=>'Энэ мөр тайлан болгон илгээхэд хэт урт тул түүнд тайлангийн маягт санал болгохгүй.','Category'=>'Ангилал','Choose a category…'=>'Ангилал сонгох…','Roll back and send report'=>'Буцааж, тайлан илгээх','Send report'=>'Тайлан илгээх','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Энэ бүрэлдэхүүн хэсгийн зарим Текстийг зохиогч нь кодод шууд бичсэн тул хэлний багцаар орчуулах боломжгүй.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Загвартай хамт ирсэн','Bundled with the plugin'=>'Плагинтай хамт ирсэн','Upload was not accepted'=>'Байршуулалтыг хүлээн аваагүй','Upload expired before it finished'=>'Байршуулалт дуусахаас өмнө хугацаа дууссан','No translation'=>'Орчуулга байхгүй','Upload in progress — continue or cancel'=>'Байршуулалт явагдаж байна — үргэлжлүүлэх эсвэл цуцлах','Scheduled, waiting to be processed'=>'Товлосон, боловсруулахыг хүлээж байна','Translating…'=>'Орчуулж байна…','Translation failed'=>'Орчуулга амжилтгүй боллоо','Free quota used'=>'Үнэгүй квот дууссан','Needs a paid license'=>'Төлбөртэй лиценз шаардлагатай','Not supported'=>'Дэмжигдээгүй','Status unknown'=>'Төлөв тодорхойгүй','translation statusInstalled'=>'Суулгасан','Update available'=>'Шинэчлэл бэлэн','Removed after a failed integrity check'=>'Бүрэн бүтэн байдлын шалгалт амжилтгүй болсны дараа устгагдсан','Installed · built for %s, new version scheduled'=>'Суулгасан · %s-д зориулан бүтээгдсэн, шинэ хувилбарыг товлосон','Installed · built for a different version, new version scheduled'=>'Суулгасан · өөр хувилбарт зориулан бүтээгдсэн, шинэ хувилбарыг товлосон','Installed · built for %s, translating the new version…'=>'Суулгасан · %s-д зориулан бүтээгдсэн, шинэ хувилбарыг орчуулж байна…','Installed · built for a different version, translating the new version…'=>'Суулгасан · өөр хувилбарт зориулан бүтээгдсэн, шинэ хувилбарыг орчуулж байна…','Installed · built for %1$s, this site has %2$s'=>'Суулгасан · %1$s-д зориулан бүтээгдсэн, энэ сайт %2$s хувилбартай','Installed · built for %s'=>'Суулгасан · %s-д зориулан бүтээгдсэн','Installed · built for a different version'=>'Суулгасан · өөр хувилбарт зориулан бүтээгдсэн','Installed · built for %s, new version failed'=>'Суулгасан · %s-д зориулан бүтээсэн, шинэ хувилбар амжилтгүй боллоо','Installed · built for a different version, new version failed'=>'Суулгасан · өөр хувилбарт зориулан бүтээсэн, шинэ хувилбар амжилтгүй боллоо','Installed · built for %s, new version needs a paid license'=>'Суулгасан · %s-д зориулан бүтээсэн, шинэ хувилбарт төлбөртэй лиценз шаардлагатай','Installed · built for a different version, new version needs a paid license'=>'Суулгасан · өөр хувилбарт зориулан бүтээсэн, шинэ хувилбарт төлбөртэй лиценз шаардлагатай','Installed · built for %s, free quota used'=>'Суулгасан · %s-д зориулан бүтээсэн, үнэгүй квот дууссан','Installed · built for a different version, free quota used'=>'Суулгасан · өөр хувилбарт зориулан бүтээсэн, үнэгүй квот дууссан','translation statusAvailable'=>'Боломжтой','Installed · %s'=>'Суулгасан · %s','Available · %s'=>'Боломжтой · %s','Update'=>'Шинэчлэх','Download'=>'Татах','Updating…'=>'Шинэчилж байна…','Downloading…'=>'Татаж байна…','Retry request'=>'Хүсэлтийг дахин илгээх','Request newer translation'=>'Шинэ орчуулга хүсэх','Request translation'=>'Орчуулга хүсэх','Requesting…'=>'Хүсэж байна…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Орчуулга хүсэхэд таны үнэгүй слотуудын нэг ашиглагдана, хэрэв энэ бүрэлдэхүүн хэсэг аль хэдийн нэгийг ашиглаагүй бол. Амжилтгүй болсон орчуулга слотыг буцааж өгөхгүй.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Хэрэв энэ бүрэлдэхүүн хэсэг таны үнэгүй слотуудын нэгийг хараахан ашиглаагүй бол орчуулга хүсэхэд нэг слот ашиглагдана. Амжилтгүй болсон орчуулга слотыг буцааж өгөхгүй. Үргэлжлүүлэх үү?','No plugins or themes found.'=>'Плагин эсвэл сэдэв олдсонгүй.','Clear filters'=>'Шүүлтүүрийг цэвэрлэх','No components match these filters. %s'=>'Эдгээр шүүлтүүрт тохирох бүрэлдэхүүн хэсэг алга. %s','Select all'=>'Бүгдийг сонгох','All'=>'Бүгд','Available'=>'Боломжтой','Updates'=>'Шинэчлэлтүүд','Requestable'=>'Хүсэх боломжтой','Installed'=>'Суулгасан','Plugins'=>'Плагинууд','Themes'=>'Сэдвүүд','All languages'=>'Бүх хэл','%d to install'=>'%d суулгах' . "\0" . '%d суулгах','Language:'=>'Хэл:','Bulk actions apply to every matching language of each selected component.'=>'Бөөнөөр хийх үйлдлүүд сонгосон бүрэлдэхүүн хэсэг бүрийн тохирох бүх хэлэнд хамаарна.','Bulk actions apply only to the selected language of each selected component.'=>'Бөөнөөр хийх үйлдлүүд сонгосон бүрэлдэхүүн хэсэг бүрийн зөвхөн сонгосон хэлэнд хамаарна.','Version %s'=>'Хувилбар %s','Theme · %s'=>'Сэдэв · %s','Plugin · %s'=>'Плагин · %s','Remove the %2$s translation of %1$s from this site?'=>'%1$s-ийн %2$s хэл дээрх орчуулгыг энэ сайтаас устгах уу?','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s-ийн %2$s хэл дээрх орчуулгыг өмнөх хувилбар руу буцаах уу?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Бүртгэлийн сорилт хүлээгдэж буй хэлбэртэй биш байна.','That is not a valid build identifier.'=>'Энэ нь хүчинтэй бүтээлтийн танигч биш байна.','Refusing to write outside the Babilim language-file directory.'=>'Babilim-ийн хэлний файлын лавлахаас гадна бичихээс татгалзаж байна.','Could not write the downloaded package to disk.'=>'Татаж авсан багцыг диск рүү бичиж чадсангүй.','Unexpected HTTP %d response.'=>'Хүлээгдээгүй HTTP %d хариу ирлээ.','This site\'s URL, so the service can verify you own it.'=>'Энэ сайтын URL. Үүгээр үйлчилгээ таныг сайтын эзэмшигч гэдгийг баталгаажуулна.','Your WordPress version, to serve compatible translation files.'=>'Таны WordPress-ийн хувилбар. Нийцтэй орчуулгын файл өгөхөд ашиглана.','Your PHP version, for compatibility.'=>'Таны PHP-ийн хувилбар. Нийцтэй байдлыг шалгахад ашиглана.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Энэ плагины өөрийн хувилбар. Хэт хуучирсан тул үйлчилгээтэй холбогдох боломжгүй бол үйлчилгээ танд шинэчлэхийг хэлж чадна.','This site\'s configured locale.'=>'Энэ сайтад тохируулсан хэлний бүс.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Энэ сайтад ашиглагдаж буй бүх хэлний бүс (сайтын хэлний бүс, суулгасан хэлний багцууд, хэрэглэгчийн хэлний бүс, мөн таны гараар нэмсэн бүх бүс). Аль нэг бүсийг бусдаас нь ялгаж үздэггүй.','(a public key generated for this site)'=>'(энэ сайтад зориулж үүсгэсэн нийтийн түлхүүр)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Энэ сайтын суулгалтын нийтийн түлхүүр. Хүсэлтүүд үнэхээр энэ сайтаас ирж буйг батлахад ашиглана. Зөвхөн нийтийн хэсгийг нь илгээнэ.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Суулгасан бүх плагин/сэдэв тус бүрийн: slug, хувилбар, текст домэйн, wp.org-д бүртгэлтэй эсэх, өөрийн багтсан хэлний бүсүүд, мөн аль хэлний бүсэд Babilim-ийн орчуулгыг аль хэдийн суулгасан зэрэг.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Зөвхөн WordPress.org-д байхгүй плагин эсвэл сэдвийн байршуулалтыг баталгаажуулсан үед: тухайн бүрэлдэхүүн хэсгийн бүх лавлахыг zip хэлбэрээр илгээнэ.','(generic codes and coordinates only)'=>'(зөвхөн ерөнхий код болон координат)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Хүлээгдэж буй 20 хүртэлх оношилгооны үйл явдал (жишээ нь бүрэн бүтэн байдлын шалгалтад бүтэлгүйтсэн файл). Тус бүр нь зөвхөн код, бүрэлдэхүүн хэсэг, хэлний бүсээс бүрдэх бөгөөд мөрийн агуулга эсвэл орчуулсан текстийг хэзээ ч агуулахгүй.','Unsafe locale: %s'=>'Аюултай хэлний бүс: %s','Manifest unavailable: %s'=>'Манифест боломжгүй: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Идэвхтэй бүрэлдэхүүн хэсгүүдийг тодорхойлж чадсангүй; одоо байгаа нэгтгэсэн индексийг өөрчлөөгүй.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Суулгасан плагин/сэдвүүдийг тодорхойлж чадсангүй; цэвэрлэгээг алгассан, юу ч устгаагүй.','Sweep aborted without orphaning anything: %s.'=>'Цэвэрлэгээг юуг ч өнчрүүлэлгүй зогсоолоо: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Цэвэрлэгээ ажилласан боловч зарим өөрчлөлтийг орчуулгын индексэд бүртгэж чадсангүй; дараагийн цэвэрлэгээ дахин оролдоно.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\'-ийн нэгтгэсэн индексийг дахин байгуулсан боловч орчуулгын индекс үүнийг бүртгэж чадсангүй; дараагийн дахин байгуулалт дахин оролдоно.','Could not write the staged merged index.'=>'Түр хадгалсан нэгтгэсэн индексийг бичиж чадсангүй.','Re-parsed entry count did not match the built index.'=>'Дахин задлан шинжилсэн оруулгын тоо байгуулсан индекстэй таарсангүй.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\'-ийн нэгтгэсэн индексийг байрлуулж чадсангүй; Өмнөх удаа ашиглагдаж байсан индексийг (байсан бол) хагас шинэчлэгдсэн хэвээр нь үлдээхийн оронд устгасан. Дараагийн амжилттай дахин бүтээлт хүртэл энэ хэлний бүсэд default домэйны нэмэлт орчуулга ашиглагдахгүй.','Could not open zip: %s'=>'Zip-ийг нээж чадсангүй: %s','Zip has no manifest.json.'=>'Zip-д manifest.json алга.','manifest.json in the zip is not valid JSON.'=>'Zip доторх manifest.json нь хүчинтэй JSON биш байна.','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json-ийн \'%s\' нь хүлээгдэж буй утгатай таарахгүй байна.','Another installation is running; try again in a moment.'=>'Өөр суулгалт ажиллаж байна; жаахан хүлээгээд дахин оролдоно уу.','Not a valid server_build_id: %s'=>'Хүчинтэй server_build_id биш: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Багцын манифестийн төрөл \'%1$s\' нь хүссэн төрөл \'%2$s\'-тэй таарахгүй байна.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Багцын текст домэйн \'%1$s\' нь энэ сайтын бүрэлдэхүүн хэсгийн хуулбарын (\'%2$s\') текст домэйнтэй таарахгүй тул суулгаагүй.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Өгсөн домэйн \'%1$s\' нь багцын манифестийн өөрийн slug \'%2$s\'-тэй ч, text_domain \'%3$s\'-тэй ч таарахгүй байна.','Unsafe slug: %s'=>'Аюултай slug: %s','Unsafe text_domain: %s'=>'Аюултай text_domain: %s','The package has no %s for its own text domain.'=>'Багц нь өөрийн текст домэйнд зориулсан %s файлгүй байна.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json дутуу эсвэл \'%s\' талбар буруу байна.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json дутуу эсвэл \'entries\' буруу байна.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json дутуу эсвэл \'files\' буруу байна.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json дутуу эсвэл \'extra_domains\' буруу байна.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json дутуу эсвэл \'build_no\' буруу байна.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json доторх \'server_build_id\' нь хүчинтэй build id биш байна.','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json доторх \'contract\' нь хүчинтэй хувилбарын тэмдэгт мөр биш байна.','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json доторх \'status\' нь \'published\' байх ёстой.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json доторх \'kind\' нь \'plugin\' эсвэл \'theme\' байх ёстой.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json доторх \'default_domain_entries\' буруу байна.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json доторх \'default_domain_files\' буруу байна.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest дутуу эсвэл \'%s\' талбар буруу байна.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest доторх \'server_build_id\' нь хүчинтэй build id биш байна.','No record for %s'=>'%s-д зориулсан бүртгэл олдсонгүй','One or more served files no longer match the manifest.'=>'Нэг буюу хэд хэдэн үйлчилсэн файл manifest-тэй таарахаа больсон.','No previous build to roll back to.'=>'Буцаах өмнөх build байхгүй байна.','The change could not be recorded in the translation index; please try again.'=>'Өөрчлөлтийг орчуулгын индекст бүртгэж чадсангүй. Дахин оролдоно уу.','Unknown kind: %s'=>'Үл мэдэгдэх kind: %s','Unsafe domain: %s'=>'Аюултай домэйн: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'\'%1$s\' текст домэйн (%2$s) өөр суулгасан бүрэлдэхүүн хэсэгт (%3$s) аль хэдийн үйлчилж байна. Юу ч суулгаагүй.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Буцаах нь \'%1$s\' (%2$s) файлыг дарж бичих болно. Энэ файл одоо өөр суулгасан бүрэлдэхүүн хэсэгт (%3$s) үйлчилж байна. Юу ч өөрчлөгдөөгүй.','Zip is missing expected file: %s'=>'Zip-д шаардлагатай файл байхгүй байна: %s','sha256 mismatch for %s'=>'%s-ийн sha256 таарсангүй','The package declares no main translation file.'=>'Багц үндсэн орчуулгын файлыг зарлаагүй байна.','Zip is missing expected default file: %s'=>'Zip-д шаардлагатай default файл байхгүй байна: %s','sha256 mismatch for default/%s'=>'default/%s-ийн sha256 таарсангүй','Could not stage %s'=>'%s-г түр байршуулж чадсангүй','Could not stage default/%s'=>'default/%s-г түр байршуулж чадсангүй','Entry count mismatch for %s'=>'%s-ийн бичлэгийн тоо таарсангүй','Could not verify entry count for %s'=>'%s-ийн бичлэгийн тоог шалгаж чадсангүй','l10n.php entry count mismatch for %s'=>'%s-ийн l10n.php бичлэгийн тоо таарсангүй','Default supplement entry count mismatch.'=>'Default нэмэлтийн бичлэгийн тоо таарсангүй.','The package produced no servable main translation file.'=>'Багцаас үйлчлэх боломжтой үндсэн орчуулгын файл гарсангүй.','Could not prepare %s for rollback.'=>'%s-г буцаахад бэлтгэж чадсангүй.','Could not back up %s before replacing it.'=>'%s-г солихын өмнө нөөцлөж чадсангүй.','Could not move %s into place.'=>'%s-г байранд нь шилжүүлж чадсангүй.','English (United States)'=>'Англи (Америкийн Нэгдсэн Улс)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest ашиглах боломжгүй: %s','could not read _manifest.json: %s'=>'_manifest.json-г уншиж чадсангүй: %s','failed to parse _manifest.json: %s'=>'_manifest.json-г задлан шинжилж чадсангүй: %s','_manifest.json has an unexpected structure'=>'_manifest.json нь гэнэтийн бүтэцтэй байна','Could not create the package archive.'=>'Багцын архивыг үүсгэж чадсангүй.','No writable temporary directory is available for packaging.'=>'Багцлахад ашиглах бичих боломжтой түр хавтас алга.','A file in the component could not be read, so it was not packaged.'=>'Бүрэлдэхүүн хэсэг доторх нэг файлыг уншиж чадаагүй тул багцалсангүй.','Only plugins and themes can be packaged.'=>'Зөвхөн залгаас болон загваруудыг багцалж болно.','The component\'s main file was not found.'=>'Бүрэлдэхүүн хэсгийн үндсэн файл олдсонгүй.','The component is not inside the plugins or themes directory.'=>'Бүрэлдэхүүн хэсэг нь залгаас эсвэл загваруудын хавтас дотор байхгүй байна.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim-ийн энэ алхамд зориулсан хугацаа дууссан тул дараагийн шалгалтаар үргэлжлүүлнэ.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim энэ сайтыг баталгаажуулж чадаагүй тул баталгаажуулалт амжилттай болох хүртэл юу ч татаж авахгүй, суулгахгүй.','Registration response was missing required fields.'=>'Бүртгэлийн хариунд шаардлагатай талбарууд дутуу байна.','No pending challenge to verify.'=>'Баталгаажуулах хүлээгдэж буй сорилт алга.','Verify response was missing site_token.'=>'Баталгаажуулалтын хариунд site_token дутуу байна.','Rotate-token response was missing site_token.'=>'Токен шинэчлэх хариунд site_token дутуу байна.','nonce must be a hexadecimal string.'=>'nonce нь арван зургаатын тооны мөр байх ёстой.','No pending challenge for this nonce.'=>'Энэ nonce-д хүлээгдэж буй сорилт алга.','Too many requests.'=>'Хэт олон хүсэлт илгээлээ.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Энэ сайт %2$d хэл дээр %1$d бүрэлдэхүүн хэсэгтэй тул %3$d шалгалтын багц шаардлагатай; Babilim нэг ажиллалтад дээд тал нь %4$d багц боловсруулна. Тохиргооноос удирдах хэлний тоог цөөлөх эсвэл ашиглагдаагүй залгаас, загваруудыг идэвхгүй болгоод одоо дахин шалгана уу.','Babilim could not finish checking this site.'=>'Babilim энэ сайтын шалгалтыг дуусгаж чадсангүй.','This site\'s address is too long for Babilim to register.'=>'Энэ сайтын хаяг Babilim-д бүртгэхэд хэт урт байна.','This site\'s locale code is not one Babilim can register.'=>'Энэ сайтын хэлний код Babilim бүртгэх боломжгүй код байна.','The download response was missing a usable location.'=>'Татаж авах хариунд ашиглах боломжтой байршил алга байна.','The service\'s upload offer was incomplete.'=>'Үйлчилгээний байршуулах санал бүрэн бус байлаа.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Энэ бүрэлдэхүүн хэсэг үйлчилгээний хүлээн авах хэмжээнээс том тул байршуулах боломжгүй.','The packaged component could not be read.'=>'Багцалсан бүрэлдэхүүн хэсгийг уншиж чадсангүй.','A part of the upload kept failing, so the upload was cancelled.'=>'Байршуулалтын нэг хэсэг удаа дараа амжилтгүй болсон тул байршуулалтыг цуцаллаа.','Could not read: %s'=>'Уншиж чадсангүй: %s']];